package.path='Tools/lua/?.lua;'..package.path
local ok=require('ok');local json=require('ok.json');local hash=require('ok.hash');local root=ok.root:gsub('\\','/'):gsub('%s+$','');local out=root..'/output/street-social-city-production/ground-pbr-v1';local envout=root..'/output/street-social-city-production/day-night-v1'
local function read(p)local f=assert(io.open(p,'rb'));local d=json.decode(f:read('*a'));f:close();return d end
local function write(p,d)local f=assert(io.open(p,'wb'));f:write(type(d)=='string' and d or json.encode(d));f:close()end
local function esc(s)return tostring(s):gsub('&','&amp;'):gsub('<','&lt;'):gsub('>','&gt;'):gsub('"','&quot;')end
local install=read(out..'/install.json');local audit=read(out..'/audit.json');local files=read(out..'/verification.json');local views=read(out..'/captures.json');local review=read(out..'/visual-review.json');local runtime=read(envout..'/runtime-package-launch.json');local package=read(envout..'/package.json');local native=read(runtime.native_receipt);local upper=read(out..'/verify.json');local complete=read(out..'/complete.json')
local normal_fix=read(out..'/normal_fix.json');local coverage=read(out..'/coverage.json')
assert(normal_fix.status=='passed' and normal_fix.map_sha256==install.map_sha256 and normal_fix.source_binding_audit_sha256==hash.sha256_file(out..'/audit.json') and coverage.status=='passed')
assert(views.package_id==package.id and review.package_id==package.id and runtime.executable==package.target..'/Stage/Windows/StreetSocialCity/Binaries/Win64/StreetSocialCity.exe','Evidence must come from the exact final package')
assert(files.status=='passed' and files.passed==48 and files.failed==0 and audit.status=='passed' and review.status=='passed')
for _,r in ipairs({audit,views,review,runtime,package,complete})do assert(r.map_sha256==install.map_sha256)end
assert(runtime.status=='passed' and package.exit_code==0 and package.engine=='E:/PhysX/UE5.8' and native.status=='passed' and native.world_type=='Game' and not native.python_module_loaded)
assert(hash.sha256_file(root..'/StreetSocialCity/Content/UniversityCity/Maps/UniversityCity.umap')==install.map_sha256)
local pics={};for _,v in ipairs(views.images)do assert(hash.sha256_file(v.path)==v.sha256);pics[v.id]=v end
local function relative(path)assert(path:sub(1,#out+1)==out..'/');return path:sub(#out+2)end
